# ==============================================================================
# ByteFix Optimizer - Suite Completa con Interfaz Gráfica (WPF)
# Repositorio: https://github.com/Dxb-2004/ByteFix
# Uso directo: irm https://raw.githubusercontent.com/Dxb-2004/ByteFix/main/ByteFix.ps1 | iex
# ==============================================================================
param (
    [string]$Config,
    [ValidateSet("Standard", "Minimal", "Advanced", "")]
    [string]$Preset,
    [switch]$Offline
)

# Forzar protocolos de red seguros
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls13

# Auto-elevación a Administrador si se ejecuta sin permisos
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Host "[ByteFix] Solicitando permisos de Administrador..." -ForegroundColor Yellow
    if ($PSCommandPath -and (Test-Path -Path $PSCommandPath)) {
        Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
    } else {
        $remoteCmd = "irm https://raw.githubusercontent.com/Dxb-2004/ByteFix/main/ByteFix.ps1 | iex"
        Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -Command `"$remoteCmd`"" -Verb RunAs
    }
    return
}

